"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { ChevronDown, Check, FolderOpen, Plus, Search } from "lucide-react";
import { useWorkspaceContext } from "@/features/workspaces/context/WorkspaceContext";
import { ImportModal } from "@/features/workspaces/components/ImportModal/ImportModal";
import type { LocalWorkspaceSummary } from "@/services/workflow-backend";

const AVATAR_CLASSES = [
  "bg-purple",
  "bg-success",
  "bg-primary",
  "bg-warning",
  "bg-danger",
];

function getWorkspaceInitials(name: string): string {
  return (
    name
      .split(/[\s-_]+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((p) => p[0]?.toUpperCase() ?? "")
      .join("")
      .slice(0, 2) || "W"
  );
}

function getWorkspaceAvatarClass(summary: LocalWorkspaceSummary): string {
  const seed = `${summary.workspaceId}${summary.name}`;
  const total = Array.from(seed).reduce(
    (sum, char) => sum + char.charCodeAt(0),
    0,
  );
  return AVATAR_CLASSES[total % AVATAR_CLASSES.length] ?? "bg-purple";
}

function WorkspaceItem({
  summary,
  isSelected,
  onSelect,
}: {
  summary: LocalWorkspaceSummary;
  isSelected: boolean;
  onSelect: (id: string) => void;
}) {
  const initials = getWorkspaceInitials(summary.name);

  return (
    <button
      type="button"
      role="option"
      aria-selected={isSelected}
      onClick={() => onSelect(summary.workspaceId)}
      className={
        "flex w-full items-center gap-2.5 px-2.5 py-2 text-left transition-colors hover:bg-surface-subtle " +
        (isSelected ? "bg-surface-subtle" : "")
      }
    >
      <div
        className={
          "flex h-5 w-5 shrink-0 items-center justify-center rounded-sm text-[9px] font-bold text-white " +
          getWorkspaceAvatarClass(summary)
        }
        aria-hidden="true"
      >
        {initials}
      </div>
      <div className="min-w-0 flex-1">
        <p className="truncate text-[11px] font-semibold leading-4 text-text-primary">
          {summary.name}
        </p>
        <p className="truncate text-[10px] leading-3 text-text-muted">
          {summary.repo_url}
        </p>
      </div>
      {isSelected && (
        <Check className="h-3 w-3 shrink-0 text-success" aria-hidden="true" />
      )}
    </button>
  );
}

export function WorkspaceSwitcher() {
  const {
    summaries,
    selectedWorkspaceId,
    selectWorkspace,
    goToBoard,
    activeSurface,
  } = useWorkspaceContext();
  const [open, setOpen] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [search, setSearch] = useState("");
  const ref = useRef<HTMLDivElement>(null);

  const filteredSummaries = summaries.filter(
    (s) =>
      !search ||
      s.name.toLowerCase().includes(search.toLowerCase()) ||
      s.repo_url.toLowerCase().includes(search.toLowerCase()),
  );

  const handleSelect = useCallback(
    (workspaceId: string) => {
      if (workspaceId !== selectedWorkspaceId) {
        selectWorkspace(workspaceId);
      }
      setOpen(false);
      setSearch("");
    },
    [selectedWorkspaceId, selectWorkspace],
  );

  const handleImportSuccess = useCallback(() => {
    setShowImport(false);
    setOpen(false);
    setSearch("");
  }, []);

  const handleGoToBoard = useCallback(() => {
    setOpen(false);
    setSearch("");
    goToBoard();
  }, [goToBoard]);

  useEffect(() => {
    if (!open) return;
    function handlePointerDown(e: PointerEvent) {
      if (!ref.current?.contains(e.target as Node)) {
        setOpen(false);
        setSearch("");
      }
    }
    document.addEventListener("pointerdown", handlePointerDown);
    return () => document.removeEventListener("pointerdown", handlePointerDown);
  }, [open]);

  const activeSummary = summaries.find(
    (s) => s.workspaceId === selectedWorkspaceId,
  );

  const isBoardActive = activeSurface === "board";

  return (
    <>
      <div ref={ref} className="relative">
        <div
          className={
            "flex h-8 w-60 overflow-hidden border text-left transition-colors " +
            (isBoardActive
              ? "border-success/60 bg-success-bg/35 hover:border-success hover:bg-success-bg/50"
              : "border-border bg-surface-secondary hover:bg-surface-subtle")
          }
        >
          <button
            type="button"
            aria-label="Back to kanban board"
            onClick={handleGoToBoard}
            className="flex min-w-0 flex-1 items-center gap-2 px-2.5 text-left"
          >
            <FolderOpen
              className={
                "h-4 w-4 shrink-0 " +
                (isBoardActive ? "text-success" : "text-text-muted")
              }
              strokeWidth={2}
              aria-hidden="true"
            />
            <span className="min-w-0 truncate text-xs font-semibold leading-none text-text-secondary">
              {activeSummary?.name ?? "Select workspace"}
            </span>
          </button>
          <button
            type="button"
            aria-haspopup="listbox"
            aria-expanded={open}
            aria-label="Switch workspace"
            onClick={() => setOpen((v) => !v)}
            className={
              "ml-auto flex h-full w-8 shrink-0 items-center justify-center border-l transition-colors " +
              (isBoardActive
                ? "border-success/25 bg-success-bg/70 hover:bg-success-bg"
                : "border-border bg-surface-secondary hover:bg-surface-subtle")
            }
          >
            <ChevronDown
              className={
                "h-3.5 w-3.5 shrink-0 transition-transform " +
                (isBoardActive ? "text-success " : "text-text-muted ") +
                (open ? "rotate-180" : "")
              }
              aria-hidden="true"
            />
          </button>
        </div>

        {open && (
          <div
            role="listbox"
            aria-label="Available workspaces"
            className="absolute left-0 top-full z-40 mt-2 w-72 border border-border bg-surface shadow-lg"
          >
            <div className="border-b border-border bg-surface-secondary px-2.5 py-2">
              <div className="mb-2 text-[10px] font-semibold uppercase tracking-wide text-text-secondary">
                Switch Workspace
              </div>
              <label className="flex h-8 items-center gap-2 border border-border bg-surface px-2">
                <Search
                  className="h-3.5 w-3.5 shrink-0 text-text-muted"
                  aria-hidden="true"
                />
                <input
                  type="search"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="Search workspaces..."
                  autoFocus
                  className="min-w-0 flex-1 bg-transparent text-[11px] text-text-primary outline-none placeholder:text-text-muted"
                  aria-label="Search workspaces"
                />
              </label>
            </div>

            {filteredSummaries.length > 0 ? (
              <div className="max-h-60 overflow-y-auto py-1.5">
                {filteredSummaries.map((s) => (
                  <WorkspaceItem
                    key={s.workspaceId}
                    summary={s}
                    isSelected={s.workspaceId === selectedWorkspaceId}
                    onSelect={handleSelect}
                  />
                ))}
              </div>
            ) : (
              <p className="px-3 py-3 text-xs text-text-muted">
                No workspaces found.
              </p>
            )}

            <div className="border-t border-border p-1.5">
              <button
                type="button"
                onClick={() => {
                  setOpen(false);
                  setSearch("");
                  setShowImport(true);
                }}
                className="flex w-full items-center gap-2 px-2 py-1.5 text-[11px] font-semibold text-text-primary transition-colors hover:bg-surface-subtle"
              >
                <Plus className="h-3.5 w-3.5" aria-hidden="true" />
                Import Workspace
              </button>
            </div>
          </div>
        )}
      </div>

      {showImport && (
        <ImportModal
          onClose={() => setShowImport(false)}
          onSuccess={handleImportSuccess}
        />
      )}
    </>
  );
}
"use client";

import { Layers, LogOut, X } from "lucide-react";
import type {
  FeatureTabEntry,
  TaskTabEntry,
} from "../../context/WorkspaceContext";
import { useWorkspaceContext } from "../../context/WorkspaceContext";
import { WorkspaceSwitcher } from "../WorkspaceSwitcher";
import type { SourceState } from "@/services/workflow-backend";
import { useSession } from "@/features/auth";

type WorkspaceHeaderProps = {
  workspaceName: string;
  featureCount: number;
  taskCount: number;
  sourceState?: SourceState | null;
  showMeta?: boolean;
  showTitle?: boolean;
};

function formatSyncedTime(iso: string): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;

  const hours = date.getUTCHours();
  const displayHours = hours % 12 || 12;
  const minutes = String(date.getUTCMinutes()).padStart(2, "0");
  const seconds = String(date.getUTCSeconds()).padStart(2, "0");
  const suffix = hours >= 12 ? "PM" : "AM";

  return `${displayHours}:${minutes}:${seconds} ${suffix}`;
}

function TaskHeaderTab({ entry }: { entry: TaskTabEntry }) {
  const { activeSurface, activeTaskTabId, activateTaskTab, closeTaskTab } =
    useWorkspaceContext();
  const isActive =
    activeSurface === "task-tab" && activeTaskTabId === entry.sessionId;

  function handleClick() {
    activateTaskTab(entry.sessionId);
  }

  function handleClose(e: React.MouseEvent) {
    e.stopPropagation();
    closeTaskTab(entry.sessionId);
  }

  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      activateTaskTab(entry.sessionId);
    }
  }

  return (
    <div
      role="tab"
      tabIndex={0}
      aria-selected={isActive}
      data-task-tab={entry.sessionId}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      className={
        "group flex h-8 min-w-0 max-w-55 cursor-pointer items-center gap-1.5 border px-2 text-xs transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-primary " +
        (isActive
          ? "border-success bg-success-bg text-text-primary"
          : "border-border bg-surface-secondary text-text-secondary hover:bg-surface-subtle hover:text-text-primary")
      }
    >
      <span
        className={
          "shrink-0 border px-1.5 font-mono text-[10px] font-bold leading-4 " +
          (isActive
            ? "border-success/30 bg-success-bg text-success"
            : "border-border bg-surface text-text-muted")
        }
        aria-label={`Task ${entry.taskName}`}
      >
        {entry.taskName}
      </span>
      <span className="min-w-0 truncate" title={entry.title}>
        {entry.title}
      </span>
      <button
        type="button"
        onClick={handleClose}
        aria-label={`Close ${entry.taskName} tab`}
        className="ml-0.5 shrink-0 p-0.5 text-text-muted opacity-70 transition-colors hover:bg-surface hover:text-text-primary group-hover:opacity-100"
      >
        <X className="h-3 w-3" aria-hidden="true" />
      </button>
    </div>
  );
}

function FeatureHeaderTab({ entry }: { entry: FeatureTabEntry }) {
  const {
    activeSurface,
    activeFeatureTabId,
    activateFeatureTab,
    closeFeatureTab,
  } = useWorkspaceContext();
  const isActive =
    activeSurface === "feature-tab" && activeFeatureTabId === entry.sessionId;

  function handleClick() {
    activateFeatureTab(entry.sessionId);
  }

  function handleClose(e: React.MouseEvent) {
    e.stopPropagation();
    closeFeatureTab(entry.sessionId);
  }

  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      activateFeatureTab(entry.sessionId);
    }
  }

  return (
    <div
      role="tab"
      tabIndex={0}
      aria-selected={isActive}
      data-feature-tab={entry.sessionId}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      className={
        "group flex h-8 min-w-0 max-w-55 cursor-pointer items-center gap-1.5 border px-2 text-xs transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-primary " +
        (isActive
          ? "border-success bg-success-bg text-text-primary"
          : "border-border bg-surface-secondary text-text-secondary hover:bg-surface-subtle hover:text-text-primary")
      }
    >
      <Layers
        className={
          "h-3.5 w-3.5 shrink-0 " +
          (isActive ? "text-success" : "text-text-muted")
        }
        aria-hidden="true"
      />
      <span className="min-w-0 truncate" title={entry.title}>
        {entry.title}
      </span>
      <button
        type="button"
        onClick={handleClose}
        aria-label={`Close ${entry.featureName} tab`}
        className="ml-0.5 shrink-0 p-0.5 text-text-muted opacity-70 transition-colors hover:bg-surface hover:text-text-primary group-hover:opacity-100"
      >
        <X className="h-3 w-3" aria-hidden="true" />
      </button>
    </div>
  );
}

function WorkspaceHeaderTabs({
  fallbackLabel,
  showFallbackLabel = true,
}: {
  fallbackLabel: string;
  showFallbackLabel?: boolean;
}) {
  const { openTaskTabs, openFeatureTabs } = useWorkspaceContext();
  const hasOpenTabs = openTaskTabs.length > 0 || openFeatureTabs.length > 0;

  if (!hasOpenTabs) {
    if (!showFallbackLabel) return null;
    return (
      <h1 className="min-w-0 truncate text-sm font-semibold text-text-primary">
        {fallbackLabel}
      </h1>
    );
  }

  return (
    <div
      role="tablist"
      aria-label="Open workspace tabs"
      data-workspace-header-tabs
      className="flex min-w-0 items-center gap-1 overflow-x-auto"
    >
      {openTaskTabs.map((entry) => (
        <TaskHeaderTab key={entry.sessionId} entry={entry} />
      ))}
      {openFeatureTabs.map((entry) => (
        <FeatureHeaderTab key={entry.sessionId} entry={entry} />
      ))}
    </div>
  );
}

export function WorkspaceHeader({
  workspaceName,
  featureCount,
  taskCount,
  sourceState,
  showMeta = false,
  showTitle = true,
}: WorkspaceHeaderProps) {
  const { logout } = useSession();

  return (
    <header
      data-workspace-header
      className="flex h-9 shrink-0 items-center gap-2 border-b border-border bg-surface px-4 py-0.5"
    >
      <div className="flex w-fit shrink-0 items-center">
        <WorkspaceSwitcher />
      </div>
      <div className="flex min-w-0 flex-1 items-center gap-2">
        <div className="min-w-0 flex-1">
          <WorkspaceHeaderTabs
            fallbackLabel={workspaceName}
            showFallbackLabel={showTitle}
          />
        </div>
        {showMeta && (
          <div className="flex shrink-0 items-center gap-3">
            <span className="shrink-0 text-xs text-text-secondary">
              {featureCount} features
            </span>
            <span className="shrink-0 text-xs text-text-primary">
              {taskCount} tasks
            </span>
            {sourceState?.last_synced_at && (
              <span className="hidden shrink-0 text-[11px] text-text-muted sm:inline">
                {sourceState?.stale
                  ? `⚠️ Last synced: ${formatSyncedTime(sourceState.last_synced_at)}`
                  : `synced ${formatSyncedTime(sourceState.last_synced_at)}`}
              </span>
            )}
          </div>
        )}
        <button
          type="button"
          onClick={logout}
          title="Sign out"
          aria-label="Sign out"
          className="ml-1 flex shrink-0 items-center gap-1 rounded p-1 text-text-muted transition-colors hover:bg-surface-subtle hover:text-text-primary focus:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          <LogOut className="h-3.5 w-3.5" aria-hidden="true" />
        </button>
      </div>
    </header>
  );
}

