  ],
  selectedWorkspaceId: "ws-uuid-1",
  activeSurface: "board" as string,
  selectWorkspace: vi.fn(),
  goToBoard: vi.fn(),
}));

vi.mock("@/features/workspaces/context/WorkspaceContext", () => ({
  useWorkspaceContext: () => mockWorkspaceContext,
}));

